<?php
 namespace QQWorld\Reports\Test\Constraint; use QQWorld\Customer\Test\Fixture\Customer; use QQWorld\Reports\Test\Page\Adminhtml\CustomerOrdersReport; class AssertCustomerOrderCountReportResult extends AbstractAssertCustomerOrderReportResult { public function processAssert( CustomerOrdersReport $customerOrdersReport, Customer $customer, array $columns, array $report ) { $filter = $this->prepareFilter($customer, $columns, $report); \PHPUnit_Framework_Assert::assertTrue( $customerOrdersReport->getGridBlock()->isRowVisible($filter, false), 'Order does not present in count grid.' ); } public function toString() { return 'Order count is present in count grid.'; } } 